## Code Example

```javascript
// Minimal token bucket sketch
class TokenBucket {
  constructor(rate, capacity) {
    this.rate = rate;
    this.capacity = capacity;
    this.tokens = capacity;
    this.last = Date.now();
  }
  consume(n=1){
    const now = Date.now();
    const delta = (now - this.last) * this.rate / 1000;
    this.tokens = Math.min(this.capacity, this.tokens + delta);
    this.last = now;
    if(this.tokens >= n){ this.tokens -= n; return true; }
    return false;
  }
}
```

